export const atlas = Object.fromEntries(
  rows.map(
    ([
      id,
      title,
      names,
      labels,
      trace,
      failure,
      contract,
      decision,
      source,
    ]) => {
      const ns = names.split('|'),
        ls = labels.split('|');
      const design: Design = {
        nodes: ns.map((name, i) => ({
          id: 'n' + i,
          name,
          kind: /database|storage|record|outbox|^Hash index$|^Ordered index$/i.test(
            name,
          )
            ? 'database'
            : 'class',
          detail: '',
          capacity: 1,
          replicas: 1,
        })),
        edges: ls.map((label, i) => ({
          id: 'e' + i,
          from: 'n' + i,
          to: 'n' + (i + 1),
          label,
          async: false,
        })),
      };
      return [
        id,
        {
          title,
          design,
          trace: trace.split('||'),
          failure,
          contract,
          decision,
          source,
        },
      ];
    },
  ),
) as Record<
  string,
  {
    title: string;
    design: Design;
    trace: string[];
    failure: string;
    contract: string;
    decision: string;
    source: keyof typeof reading;
  }
>;
